:root{font-family:'DM Sans',sans-serif;color:#252823;background:#f7f6f1;font-synthesis:none;--green:#245d54;--line:#dedfd7;--muted:#74776f}*{box-sizing:border-box}body{margin:0;min-width:320px}button,input,textarea,select{font:inherit}button{color:inherit}button,a{-webkit-tap-highlight-color:transparent}button{cursor:pointer}header{height:76px;display:flex;align-items:center;border-bottom:1px solid var(--line);padding:0 32px;background:#fbfaf6;position:sticky;top:0;z-index:20}.brand{width:224px;display:flex;align-items:center;gap:10px;font-family:'DM Serif Display',serif;font-size:25px;color:#202820;text-decoration:none}.brand-mark{display:grid;place-items:center;width:32px;height:32px;border-radius:9px;background:var(--green);color:white;transform:rotate(-3deg)}.search-wrap{height:42px;width:min(490px,42vw);border:1px solid #d8d9d2;border-radius:10px;background:white;display:flex;align-items:center;padding:0 12px;color:#8a8d85;box-shadow:0 1px 2px #2221}.search-wrap input{border:0;outline:0;flex:1;padding:0 10px;color:#242822;background:transparent;font-size:14px}.search-wrap kbd{background:#f1f1ed;border:1px solid #dddeda;border-radius:5px;padding:2px 7px;font-size:11px;color:#777}.add-btn{border:0;background:var(--green);color:#fff;height:42px;border-radius:10px;padding:0 16px;display:flex;align-items:center;justify-content:center;gap:8px;font-weight:600;box-shadow:0 2px 5px #143d3425}.add-btn:hover{background:#194d45}.header-spacer{}.avatar{margin-left:12px;border:0;width:40px;height:40px;border-radius:50%;background:#e7ded0;color:#655643;font-weight:600}.search-wrap+.add-btn{margin-left:auto}.layout{display:grid;grid-template-columns:256px 1fr;min-height:calc(100vh - 76px)}aside{border-right:1px solid var(--line);padding:27px 18px 22px;background:#f1f0ea;display:flex;flex-direction:column;position:sticky;top:76px;height:calc(100vh - 76px)}.aside-head{display:none}.nav-group{display:flex;flex-direction:column;gap:3px}.nav-item{border:0;background:transparent;width:100%;display:flex;align-items:center;gap:11px;padding:10px 12px;border-radius:8px;color:#686b64;text-align:left;font-size:14px}.nav-item span:nth-last-child(2){flex:1}.nav-item small{font-size:11px;background:#e5e4de;padding:2px 7px;border-radius:20px;color:#777}.nav-item:hover{background:#e9e8e2}.nav-item.active{background:#dce6e1;color:#1f584f;font-weight:600}.nav-item.active small{background:#cadbd4;color:#285d54}.nav-label{display:flex;align-items:center;justify-content:space-between;margin:28px 10px 9px;color:#8a8d85;font-size:10px;font-weight:600;letter-spacing:1.4px}.nav-label button{border:0;background:transparent;color:#777;padding:3px}.folder-dot{width:11px;height:11px;border-radius:3px}.aside-bottom{margin-top:auto}.aside-bottom>button{border:0;background:transparent;padding:10px 12px;display:flex;gap:11px;color:#6c6f68}.storage{border-top:1px solid #d9dad3;margin-top:14px;padding:18px 11px 0}.storage>div:first-child{display:flex;justify-content:space-between;align-items:center;font-size:11px;color:#767970}.storage small{font-size:9px}.meter{height:4px;background:#d8d8d2;border-radius:9px;margin-top:9px;overflow:hidden}.meter i{display:block;height:100%;background:#699087;border-radius:9px;min-width:8px}main{padding:52px clamp(30px,5vw,72px) 70px;overflow:hidden}.hero{display:flex;justify-content:space-between;align-items:flex-end;border-bottom:1px solid var(--line);padding-bottom:27px}.eyebrow{margin:0 0 8px;color:#587b72;font-size:10px;font-weight:600;letter-spacing:1.4px;display:flex;align-items:center;gap:6px}.hero h1{font-family:'DM Serif Display',serif;font-weight:400;font-size:42px;line-height:1.1;margin:0;color:#262a25}.subtitle{margin:9px 0 0;color:var(--muted);font-size:14px}.hero-actions{display:flex;gap:10px;align-items:center}.segmented{padding:3px;background:#ecece6;border-radius:8px;display:flex}.segmented button{width:34px;height:30px;border:0;background:transparent;border-radius:6px;color:#888}.segmented button.active{background:white;color:#315f57;box-shadow:0 1px 4px #3332}.sort{height:36px;border:1px solid #d8d9d2;background:#fbfaf7;border-radius:8px;padding:0 11px;display:flex;align-items:center;gap:12px;font-size:12px;color:#676a63}.content-head{height:65px;display:flex;align-items:center;justify-content:space-between}.content-head p{font-size:12px;color:#898c84}.content-head strong{color:#424640}.clear{border:0;background:transparent;color:#65756f;display:flex;gap:4px;align-items:center;font-size:12px}.bookmarks.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.card{background:#fcfbf7;border:1px solid #dcddd6;border-radius:12px;min-width:0;padding:18px 18px 0;transition:.2s ease;position:relative}.card:hover{transform:translateY(-2px);box-shadow:0 10px 28px #353b3320;border-color:#ccd0c7}.card-top{display:flex;justify-content:space-between;align-items:start}.site-icon{width:37px;height:37px;border-radius:10px;color:#fff;display:grid;place-items:center;font-family:'DM Serif Display',serif;font-size:18px;box-shadow:inset 0 0 0 1px #fff3}.card-actions{position:relative;display:flex;gap:2px}.card-actions>button{border:0;background:transparent;color:#8b8e87;padding:6px;border-radius:6px}.card-actions>button:hover{background:#f0f0eb;color:#555}.card-actions .fav.active{color:#cf5b4a}.context{position:absolute;right:0;top:34px;width:140px;padding:6px;background:white;border:1px solid var(--line);box-shadow:0 10px 30px #2223;border-radius:9px;z-index:5}.context button,.context a{display:flex;align-items:center;gap:8px;border:0;background:transparent;width:100%;padding:8px;border-radius:6px;text-decoration:none;color:#555;font-size:12px}.context button:hover,.context a:hover{background:#f4f4ef}.context .danger{color:#bd4d42}.card-body{margin-top:21px}.card-title{display:block;color:#272a26;text-decoration:none;font-family:'DM Serif Display',serif;font-size:19px;line-height:1.25;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.card-title:hover{color:var(--green)}.domain{display:flex;align-items:center;gap:5px;color:#8a8d85;margin:6px 0 12px;font-size:11px}.desc{height:40px;overflow:hidden;color:#6e716a;font-size:12px;line-height:1.55;margin:0}.tags{display:flex;gap:6px;margin-top:17px;height:24px;overflow:hidden}.tags span{background:#eeeee8;border-radius:5px;color:#6c7068;font-size:10px;padding:4px 8px}.card footer{border-top:1px solid #e5e5df;margin:15px -18px 0;padding:12px 18px;display:flex;justify-content:space-between;color:#989b94;font-size:10px}.card footer span{display:flex;align-items:center;gap:5px}.card footer .collection{color:#787c74}.bookmarks.list{display:flex;flex-direction:column;gap:10px}.bookmarks.list .card{display:grid;grid-template-columns:48px minmax(220px,1fr) 220px 210px;align-items:center;padding:14px 16px;gap:12px}.bookmarks.list .card-top{display:block}.bookmarks.list .card-actions{position:absolute;right:11px;top:10px}.bookmarks.list .card-actions .fav{display:none}.bookmarks.list .card-body{margin:0}.bookmarks.list .desc{display:none}.bookmarks.list .tags{margin:0}.bookmarks.list footer{border:0;margin:0;padding:0 42px 0 0}.empty{text-align:center;padding:80px 20px}.empty>div{width:52px;height:52px;border-radius:50%;display:grid;place-items:center;background:#e3eae6;color:#39685e;margin:auto}.empty h2{font-family:'DM Serif Display';font-weight:400;margin:15px 0 5px}.empty p{color:var(--muted);font-size:13px;margin:0 0 20px}.empty .add-btn{margin:auto}.modal-backdrop{position:fixed;inset:0;background:#222a25a8;z-index:50;display:grid;place-items:center;padding:20px;backdrop-filter:blur(3px)}.modal{width:min(560px,100%);max-height:calc(100vh - 30px);overflow:auto;background:#faf9f5;border-radius:16px;box-shadow:0 30px 80px #1118}.modal-head{padding:23px 25px 19px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between}.modal-head>div{display:flex;gap:13px}.modal-head h2{font-family:'DM Serif Display';font-weight:400;margin:0;font-size:24px}.modal-head p{color:var(--muted);font-size:12px;margin:4px 0 0}.modal-head>button{border:0;background:transparent;align-self:start;color:#777}.modal-icon{width:39px;height:39px;background:#dce8e3;color:var(--green);display:grid;place-items:center;border-radius:10px}.modal form{padding:22px 25px}.modal label{display:block;font-size:11px;font-weight:600;color:#5e625b;margin-bottom:15px}.modal label small{float:right;color:#a1a39c;font-weight:400}.modal input,.modal textarea,.modal select{display:block;width:100%;margin-top:7px;border:1px solid #d6d7d0;border-radius:8px;background:#fff;padding:11px 12px;outline:0;font-size:13px;color:#333}.modal input:focus,.modal textarea:focus,.modal select:focus{border-color:#71948c;box-shadow:0 0 0 3px #dce9e5}.modal textarea{resize:vertical;min-height:75px}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:14px}.modal-foot{border-top:1px solid var(--line);margin:8px -25px -22px;padding:17px 25px;display:flex;justify-content:flex-end;gap:9px}.modal-foot button{height:39px;border-radius:8px;padding:0 16px;font-size:12px;font-weight:600}.cancel{border:1px solid #d5d6cf;background:#fff}.save{border:0;background:var(--green);color:#fff;display:flex;align-items:center;gap:7px}.save:disabled{opacity:.45;cursor:not-allowed}.toast{position:fixed;bottom:25px;left:50%;transform:translateX(-50%);z-index:100;background:#27342f;color:white;border-radius:9px;padding:11px 16px;box-shadow:0 8px 30px #1115;display:flex;align-items:center;gap:8px;font-size:12px;animation:toast .25s ease}.mobile-menu{display:none}
@keyframes toast{from{transform:translate(-50%,10px);opacity:0}}
@media(max-width:1100px){.bookmarks.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.bookmarks.list .card{grid-template-columns:48px minmax(180px,1fr) 160px}.bookmarks.list footer{display:none}}
@media(max-width:760px){header{height:64px;padding:0 16px;gap:11px}.mobile-menu{display:grid;place-items:center;border:0;background:transparent;padding:5px}.brand{width:auto}.brand span:last-child{display:none}.search-wrap{width:auto;flex:1}.search-wrap kbd{display:none}.search-wrap+.add-btn{margin:0;width:40px;padding:0}.add-btn span{display:none}.avatar{display:none}.layout{display:block}.layout aside{position:fixed;left:0;top:0;bottom:0;width:280px;height:100vh;z-index:60;transform:translateX(-105%);transition:transform .25s ease;box-shadow:10px 0 40px #2223}.layout aside.open{transform:translateX(0)}.aside-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:25px}.aside-head .brand span:last-child{display:inline}.aside-head button{border:0;background:transparent}.scrim{position:fixed;inset:0;background:#2227;z-index:55}main{padding:34px 18px 50px}.hero{align-items:flex-start}.hero h1{font-size:35px}.hero-actions .sort{display:none}.subtitle{max-width:230px}.bookmarks.grid{grid-template-columns:1fr}.bookmarks.list .card{display:block;padding:18px}.bookmarks.list .card-top{display:flex}.bookmarks.list .card-body{margin-top:15px}.bookmarks.list .tags{margin-top:15px}.bookmarks.list footer{display:flex;margin:15px -18px 0;padding:12px 18px}.form-row{grid-template-columns:1fr}}

